// EDITE AQUI: regiões da sua área e coordenadas aproximadas (usadas só na previsão de chuva).
// Nomes: apenas letras, números, "-" e "_".
flow.set("regioes", {
  "talhao-1": { lat: -23.5500, lon: -46.6300 },
  "talhao-2": { lat: -23.5600, lon: -46.6400 }
});
return null;

const REGIOES = flow.get("regioes") || {};
const d = msg.payload;
if (typeof d !== "object" || d === null) return null;

const u = Number(d.umidade_pct);
if (!isFinite(u) || u < 0 || u > 100) { node.warn("umidade inválida"); return null; }

const reg = REGIOES[d.regiao];
if (!reg) { node.warn("região desconhecida: " + d.regiao); return null; }

msg.leitura = {
  ponto_id: d.ponto_id, regiao: d.regiao,
  umidade_pct: u, valor_bruto: d.valor_bruto,
  lat: reg.lat, lon: reg.lon
};
return msg;

const l = msg.leitura;
msg.measurement = "umidade_solo";
msg.payload = [
  { umidade_pct: l.umidade_pct, valor_bruto: l.valor_bruto },  // fields
  { regiao: l.regiao, ponto_id: l.ponto_id }                   // tags
];
return msg;

const l = msg.leitura;
const TTL = 30 * 60 * 1000;               // cache de 30 min por região
const cache = flow.get("chuva_" + l.regiao);
if (cache && Date.now() - cache.t < TTL) {
  msg.chuva = cache;
  return [null, msg];                      // saída 2: pula a chamada HTTP
}
msg.url = "https://api.openweathermap.org/data/2.5/forecast"
        + "?lat=" + l.lat + "&lon=" + l.lon
        + "&units=metric&cnt=8&appid=" + env.get("OPENWEATHER_KEY");
return [msg, null];                        // saída 1: consulta a API

const l = msg.leitura;
const ok = msg.statusCode === 200 && msg.payload && Array.isArray(msg.payload.list);
if (!ok) {
  node.warn("OpenWeather falhou: HTTP " + msg.statusCode);
  // cache de falha: tenta de novo em ~1 min (evita chamar a API a cada leitura)
  const falha = { t: Date.now() - 29 * 60 * 1000, mm: 0, pop: 0, indisponivel: true };
  flow.set("chuva_" + l.regiao, falha);
  msg.chuva = falha;
  return [msg, null];
}
const lista = msg.payload.list;
const mm  = lista.reduce((s, p) => s + ((p.rain && p.rain["3h"]) || 0), 0);
const pop = Math.max(0, ...lista.map(p => p.pop || 0));
const chuva = { t: Date.now(), mm: mm, pop: pop };
flow.set("chuva_" + l.regiao, chuva);
msg.chuva = chuva;

// saída 2: grava a previsão no Influx (Dashboard 2)
const f = {
  measurement: "previsao_chuva",
  payload: [{ mm_24h: mm, prob_max: pop }, { regiao: l.regiao }]
};
return [msg, f];

const l = msg.leitura, c = msg.chuva;
const LIMIAR = 30;                  // % de umidade (ajuste por cultura/solo)
const CHUVA_MM = 2;                 // mm previstos em 24 h = "chuva relevante"
const COOLDOWN = 60 * 60 * 1000;    // no máx. 1 alerta por hora por ponto

if (l.umidade_pct >= LIMIAR) return null;
if (c.mm >= CHUVA_MM) return null;

const key = "alerta_" + l.regiao + "_" + l.ponto_id;
if (Date.now() - (flow.get(key) || 0) < COOLDOWN) return null;
flow.set(key, Date.now());

const chuvaTxt = c.indisponivel ? "previsão indisponível" : c.mm.toFixed(1) + " mm";
msg.url = "https://api.telegram.org/bot" + env.get("TELEGRAM_TOKEN") + "/sendMessage";
msg.headers = { "content-type": "application/json" };
msg.payload = {
  chat_id: env.get("TELEGRAM_CHAT_ID"),
  text: "⚠️ Solo seco\nRegião: " + l.regiao + " | Ponto: " + l.ponto_id +
        "\nUmidade: " + l.umidade_pct.toFixed(1) + "%" +
        "\nChuva prevista (24 h): " + chuvaTxt + "\nSugestão: irrigar."
};
return msg;

const regs = flow.get("regioes") || {};
const atual = flow.get("regiao_atual") || "(nenhuma escolhida desde o último deploy)";
const opts = Object.keys(regs).map(k =>
  `<option value="${k}"${k === atual ? " selected" : ""}>${k}</option>`).join("");
msg.statusCode = 200;
msg.headers = { "content-type": "text/html; charset=utf-8" };
msg.payload = `<!doctype html><html lang="pt-br"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>hydro-sense</title></head>
<body style="font-family:sans-serif;max-width:420px;margin:2rem auto;padding:0 1rem">
<h2>Região de monitoramento</h2>
<p>Região atual: <b>${atual}</b></p>
<form method="POST" action="/regiao">
<select name="regiao" style="font-size:1rem;padding:.5rem;width:100%">${opts}</select>
<button style="margin-top:1rem;font-size:1rem;padding:.6rem 1rem">Aplicar</button>
</form></body></html>`;
return msg;

const regs = flow.get("regioes") || {};
const regiao = msg.payload && msg.payload.regiao;
if (!regiao || !regs[regiao]) {
  msg.statusCode = 400;
  msg.headers = { "content-type": "text/plain; charset=utf-8" };
  msg.payload = "Região inválida";
  return [null, msg];
}
flow.set("regiao_atual", regiao);
const mqttMsg = { topic: "robo/jackal/solo/regiao", payload: regiao, qos: 1, retain: true };
msg.statusCode = 303;
msg.headers = { location: "/regiao" };
msg.payload = "";
return [mqttMsg, msg];
